def parse_version(v):
    # detect modifiers
    modifier = None
    base = v

    if "+" in v:
        base, modifier = v.split("+", 1)

    base_version = Version(base)

    if modifier is None:
        return (0, base_version, 0)

    # extract numeric part if present
    m = re.search(r'\d+', modifier)
    modnum = int(m.group()) if m else 0

    return (1, base_version, modnum)

